/**
 * Monthly prediction — combines Sun transit periods (one per sidereal sign,
 * generated by services/varshaphal.py --monthly) with Sarvashtavarga points
 * and the Jupiter house-from-Moon modifier to produce a narrative per period.
 *
 * Period text is composed from db/monthly-predictions.json so the wording can
 * be tuned without touching code.
 */

const { getMonthlyRaw } = require('./varshaphal');
const predictions = require('../db/monthly-predictions.json');

// Sarvashtavarga point bands. Standard cutoffs in classical Vedic literature:
// average for any sign is ~28 (337 / 12); ≥30 is auspicious, <25 is weak.
const HIGH_BINDU = 30;
const LOW_BINDU = 25;

function bandFor(points) {
  if (points >= HIGH_BINDU) return 'high';
  if (points < LOW_BINDU) return 'low';
  return 'neutral';
}

function predictionForPeriod(period) {
  const sunHouse = String(period.sunHouseFromMoon);
  const jupHouse = String(period.jupiterHouseFromMoon);
  const block = predictions.sunFromMoon[sunHouse];
  if (!block) {
    return {
      band: bandFor(period.sarvashtavargaPoints),
      theme: '',
      text: '',
    };
  }
  const band = bandFor(period.sarvashtavargaPoints);
  const base = block[band] || block.neutral;
  const jupiterModifier = predictions.jupiterFromMoonModifier[jupHouse] || '';

  return {
    band,
    theme: block.theme,
    text: jupiterModifier ? `${base} ${jupiterModifier}` : base,
  };
}

async function getMonthlyPrediction(birthData, year) {
  const raw = await getMonthlyRaw(birthData, year);
  const periods = raw.periods.map(p => {
    const pred = predictionForPeriod(p);
    return {
      ...p,
      band: pred.band,
      theme: pred.theme,
      prediction: pred.text,
    };
  });

  return {
    year,
    varshapravesh: raw.varshapravesh,
    nextVarshapravesh: raw.nextVarshapravesh,
    natalMoonSign: raw.natalMoonSign,
    natalMoonSignVedic: raw.natalMoonSignVedic,
    periods,
  };
}

module.exports = {
  getMonthlyPrediction,
  predictionForPeriod,
  bandFor,
};
